import React, { useState, useEffect } from 'react';
import axios from 'axios';

export default function ManageClasses() {
  const [classes, setClasses] = useState([]);
  const [showForm, setShowForm] = useState(false);
  const [formData, setFormData] = useState({ day: 'Monday', grade: 'Grade 10', subject: 'Mathematics', time_slot: '3.00 PM - 6.00 PM', teacher: 'Charaka Dikwella' });

  const fetchClasses = () => {
    axios.get('http://localhost:8081/api/timetable').then(res => setClasses(res.data));
  };

  useEffect(() => { fetchClasses(); }, []);

  const handleSubmit = (e) => {
    e.preventDefault();
    axios.post('http://localhost:8081/api/timetable', formData).then(res => {
      if(res.data.status === "Success") {
        fetchClasses();
        setShowForm(false);
        alert("✅ Class Schedule Added Successfully!");
      }
    });
  };

  return (
    <div style={{ padding: '30px', fontFamily: 'sans-serif' }}>
      <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: '20px' }}>
        <h2>📅 Manage Class Timetable</h2>
        <button onClick={() => setShowForm(true)} style={{ padding: '10px 20px', backgroundColor: '#15803d', color: 'white', border: 'none', borderRadius: '8px', cursor: 'pointer', fontWeight: 'bold' }}>+ Add New Class</button>
      </div>

      {showForm && (
        <div style={{ position: 'fixed', top: 0, left: 0, width: '100%', height: '100%', backgroundColor: 'rgba(0,0,0,0.5)', display: 'flex', justifyContent: 'center', alignItems: 'center', zIndex: 1000 }}>
          <div style={{ backgroundColor: 'white', padding: '30px', borderRadius: '12px', width: '450px' }}>
            <h3>Add Class Schedule</h3>
            <form onSubmit={handleSubmit} style={{ display: 'flex', flexDirection: 'column', gap: '15px' }}>
              <select value={formData.day} onChange={(e) => setFormData({...formData, day: e.target.value})} style={inputStyle}>
                {['Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday', 'Sunday'].map(d => <option key={d} value={d}>{d}</option>)}
              </select>
              <select value={formData.grade} onChange={(e) => setFormData({...formData, grade: e.target.value})} style={inputStyle}>
                {['Grade 06', 'Grade 07', 'Grade 08', 'Grade 09', 'Grade 10', 'Grade 11', 'A/L 2026', 'A/L 2027'].map(g => <option key={g} value={g}>{g}</option>)}
              </select>
              <select value={formData.subject} onChange={(e) => setFormData({...formData, subject: e.target.value})} style={inputStyle}>
                {['Mathematics', 'Science', 'English', 'Sinhala', 'ICT', 'Accounting', 'Business Studies', 'Economics', 'Physics'].map(s => <option key={s} value={s}>{s}</option>)}
              </select>
              <input type="text" placeholder="Time Slot (e.g. 3.00 PM - 6.00 PM)" value={formData.time_slot} onChange={(e) => setFormData({...formData, time_slot: e.target.value})} required style={inputStyle} />
              <input type="text" placeholder="Teacher Name" value={formData.teacher} onChange={(e) => setFormData({...formData, teacher: e.target.value})} required style={inputStyle} />
              <div style={{ display: 'flex', gap: '10px' }}>
                <button type="button" onClick={() => setShowForm(false)} style={{ flex: 1, padding: '10px', backgroundColor: '#cbd5e1', border: 'none', borderRadius: '8px' }}>Cancel</button>
                <button type="submit" style={{ flex: 1, padding: '10px', backgroundColor: '#15803d', color: 'white', border: 'none', borderRadius: '8px' }}>Save</button>
              </div>
            </form>
          </div>
        </div>
      )}

      <table style={{ width: '100%', borderCollapse: 'collapse', marginTop: '20px' }}>
        <thead style={{ backgroundColor: '#15803d', color: 'white' }}>
          <tr><th style={thStyle}>Day</th><th style={thStyle}>Grade</th><th style={thStyle}>Subject</th><th style={thStyle}>Time</th><th style={thStyle}>Teacher</th></tr>
        </thead>
        <tbody>
          {classes.map(c => (
            <tr key={c.id} style={{ borderBottom: '1px solid #e2e8f0' }}><td style={tdStyle}>{c.day}</td><td style={tdStyle}>{c.grade}</td><td style={tdStyle}>{c.subject}</td><td style={tdStyle}>{c.time_slot}</td><td style={tdStyle}>{c.teacher}</td></tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}
const inputStyle = { padding: '10px', borderRadius: '8px', border: '1px solid #cbd5e1' };
const thStyle = { padding: '12px', textAlign: 'left' };
const tdStyle = { padding: '12px' };
